using ToneCustoms.ShellStudio.Core;
namespace ToneCustoms.ShellStudio.Editor;
public enum TransformMode { Move, Rotate, Scale }
public sealed class EditorSession { public ShellProject Project {get;private set;}=new(); public SceneObject? Selected {get;private set;} public TransformMode Mode {get;set;}=TransformMode.Move; public event Action? Changed; public void NewProject(string name){Project=new(){Name=name};Selected=null;Changed?.Invoke();} public void LoadProject(ShellProject p){Project=p;Selected=null;Changed?.Invoke();} public void Add(SceneObject o){Project.Objects.Add(o);Selected=o;Changed?.Invoke();} public void Select(Guid id){Selected=Project.Objects.FirstOrDefault(x=>x.Id==id);Changed?.Invoke();} public void DeleteSelected(){if(Selected==null)return;Project.Objects.Remove(Selected);Selected=null;Changed?.Invoke();} public SceneObject? DuplicateSelected(){if(Selected==null)return null;var p=Selected.Position;var c=new SceneObject{Name=Selected.Name+" Copy",Type=Selected.Type,Position=new(p.X+.25f,p.Y+.25f,p.Z),Rotation=new(Selected.Rotation.X,Selected.Rotation.Y,Selected.Rotation.Z),Scale=new(Selected.Scale.X,Selected.Scale.Y,Selected.Scale.Z),MaterialId=Selected.MaterialId,Collision=Selected.Collision,FloorLevel=Selected.FloorLevel};Add(c);return c;} }
